package com.cpf.starter.sftp;import java.sql.Timestamp;import java.time.Instant;import org.springframework.jdbc.core.JdbcTemplate;
public final class JdbcCpfSftpTransferLedger {private final JdbcTemplate jdbc;public JdbcCpfSftpTransferLedger(JdbcTemplate j){jdbc=j;}public void started(CpfSftpTransferRecord r){jdbc.update("INSERT INTO cpf_sftp_transfer(transfer_id,operation_code,source_path,target_path,transfer_status,byte_count,transaction_id,detail,started_at,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",r.transferId(),r.operation(),r.sourcePath(),r.targetPath(),"STARTED",0,r.transactionId(),r.detail(),Timestamp.from(r.startedAt()));}public void completed(CpfSftpTransferRecord r){int n=jdbc.update("UPDATE cpf_sftp_transfer SET transfer_status=?,byte_count=?,checksum_value=?,detail=?,completed_at=?,updated_at=CURRENT_TIMESTAMP WHERE transfer_id=? AND transfer_status='STARTED'",r.status(),r.bytes(),r.checksum(),r.detail(),Timestamp.from(r.completedAt()),r.transferId());if(n!=1)throw new IllegalStateException("SFTP transfer ledger conflict: "+r.transferId());}}
